//! 🧪️ Original ranked observations retain exact UTF8 pointers and actual work through one finite source lifecycle.
use super::*;
use crate::retained_clone::{RetainedCloneSource,RetainedCloneStep};
use crate::allocation_testing::observe_retirement_allocations as observe;
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn debit(bank:&mut RetainedCloneGrant,work:u64,p:RetainedCloneProgress){assert!(work<=bank.maximum_items as u64);assert!(p.fits(*bank));bank.maximum_items-=work as usize;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;}
#[test]
fn named_vector_rank_preserves_original_observation_work_and_closed_source(){
 let law:serde_json::Value=serde_json::from_str(include_str!("actual.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("actual.schema.json")).unwrap();assert_eq!(schema["properties"]["laws"]["const"],law["laws"]);let stock=&law["stock"];let mut bank=RetainedCloneGrant{maximum_items:stock["items"].as_u64().unwrap()as usize,maximum_copy_bytes:stock["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:stock["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:stock["release"].as_u64().unwrap()as usize,maximum_depth:stock["depth"].as_u64().unwrap()as usize};
 let(rows,heap)=observe(||law["keys"].as_array().unwrap().iter().map(|key|key.as_str().unwrap().to_owned()).collect::<Vec<_>>());let(mut born,mut freed)=heap;let pointers=rows.iter().map(|row|row.as_ptr()).collect::<Vec<_>>();let d=RetainedCloneSource::<Vec<String>>::owned_constructor_demand::<()>();let g=grant(RetirementDemand{copy_bytes:RetainedCloneSource::<Vec<String>>::constructor_copy_bytes(),capacity_bytes:d.capacity_bytes,depth:d.depth,..Default::default()});let(turn,heap)=observe(||semio_framework_value_clone_source_testing::admit_owned(rows,(),g));let work=turn.work;let(mut source,p)=turn.result.map_err(|(error,..)|error).unwrap();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));debit(&mut bank,work,p);born+=heap.0;freed+=heap.1;
 {let ranked=VecRankedKeys{original:source.borrow(),key:String::as_str};for index in 0..ranked.len(){let g=grant(ranked.rank_demand(index).unwrap());assert_eq!(g.maximum_copy_bytes,law["borrowedCopyBytes"].as_u64().unwrap()as usize);for denied in [Some(RetainedCloneGrant{maximum_items:0,..g}),g.maximum_copy_bytes.checked_sub(1).map(|maximum_copy_bytes|RetainedCloneGrant{maximum_copy_bytes,..g}),Some(RetainedCloneGrant{maximum_depth:0,..g})].into_iter().flatten(){let(turn,heap)=observe(||ranked.observe_key(index,denied));assert_eq!(turn.work,law["deniedWork"].as_u64().unwrap());assert!(turn.result.unwrap().is_none());assert_eq!(heap,(0,0));}let(turn,heap)=observe(||ranked.observe_key(index,g));let work=turn.work;let(key,p)=turn.result.unwrap().unwrap();assert_eq!(work,law["vectorObservationWork"].as_u64().unwrap());assert_eq!(p.copied_bytes,law["borrowedCopyBytes"].as_u64().unwrap()as usize);assert_eq!(heap,(0,0));assert_eq!(key.get().as_ptr(),pointers[index]);assert_eq!(serde_json::to_value(key.get()).unwrap(),law["keys"][index]);debit(&mut bank,work,p);}}
 for _ in 0..law["maximumTurns"].as_u64().unwrap(){if source.terminal_is_empty(){break}let g=grant(source.next_close_demand(4096).unwrap());let(turn,heap)=observe(||source.close_step(g));let work=turn.work;let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));debit(&mut bank,work,p);born+=heap.0;freed+=heap.1;}assert!(source.terminal_is_empty());let(turn,heap)=observe(||source.close_step(Default::default()));assert_eq!(turn.work,law["cachedWork"].as_u64().unwrap());assert!(matches!(turn.result,Ok(RetainedCloneStep::Complete(p))if p==Default::default()));assert_eq!(heap,(0,0));assert_eq!(observe(||drop(source)).1,(0,0));assert_eq!(born,freed);
}
